    situation: "Ví dụ minh họa: gửi một thư cho từng khách đủ điều kiện có thể cần đi từng dòng, vì thư là một tác động ngoài. Tổng form thì không. Tổng là một câu.",
    use: ["Việc cộng, đếm, lọc: một câu.", "Có tác động ngoài từng dòng: khi đó mới hỏi tới con trỏ.", "Mở thì đóng. Một con trỏ quên đóng là một phiên bị giữ."],
    plain: "Viết một câu. Con trỏ chỉ khi bước sau là một tác động ngoài câu, từng dòng một, và bạn chịu cái chậm.",
    precise: "Con trỏ giữ trạng thái: mở, lấy dòng, hết, đóng. Quên đóng trên một phiên web là rò. Một câu tập hợp để máy chọn cách đọc. Con trỏ cấm máy làm vậy. Nó không «chính xác hơn» GROUP BY. Nó là một vòng lập trình ngồi trên SQL.",
