    insight: "Đi từng dòng không làm phép cộng đúng hơn.",
    why: "Để một vòng «cho chắc» không thay một câu đã nói được bằng tập hợp.",
    prior: "Thủ tục đã có thể giấu nhiều câu. Con trỏ là kiểu giấu chậm nhất: cầm một dòng, làm gì đó, sang dòng sau.",
